update
    tag
set
    tag_name = #{tag.tagName},
    class_id = #{tag.classId},
    description = #{tag.description},
    update_time = #{tag.updateTime}

        ,status = #{tag.status}

where
    id = #{tag.id}

update
    tag_class
set
    class_name = #{tagClass.className},
    description = #{tagClass.description},
    update_time = #{tagClass.updateTime}

        ,status = #{tagClass.status}

where
    id = #{tagClass.id}

update topic set topic_name = #{topic.topicName}, image = #{topic.image}, description = #{topic.description}, update_time = #{topic.updateTime},
,status = #{topic.status}
where id = #{topic.id}

